                raise
        else:
            modules.append(module)

    agent_type = next(
        (
            getattr(module, "Agent")
            for module in modules
            if hasattr(module, "Agent")
        ),
        None,
    )
    if agent_type is None:
        raise ImportError("LazyBridge does not export Agent.")

    def normalize(name):
        return name.replace("_", "").lower()

    def annotations_for(cls):
        try:
            return typing.get_type_hints(cls.__init__)
        except (NameError, TypeError, AttributeError):
            return {}

    def annotation_classes(annotation):
        origin = typing.get_origin(annotation)
        if origin in (typing.Union, types.UnionType, typing.Annotated):
            arguments = typing.get_args(annotation)
            if origin is typing.Annotated:
                arguments = arguments[:1]
            return [
                cls
                for argument in arguments
                for cls in annotation_classes(argument)
            ]
        if inspect.isclass(annotation) and annotation.__module__.startswith(
            "lazybridge"
        ):
            return [annotation]
        return []

    public_classes = []
    for module in modules:
        for name, value in vars(module).items():
            if not name.startswith("_") and inspect.isclass(value):
                if value not in public_classes:
                    public_classes.append(value)

    values = {
        "name": ("checked", "name"),
        "agentname": ("checked", "name"),
        "engine": (engine, "engine"),
        "judge": (judge, "judge"),
        "outputjudge": (judge, "judge"),
        "verifier": (judge, "judge"),
        "outputverifier": (judge, "judge"),
        "maxattempts": (2, "attempts"),
        "maxverificationattempts": (2, "attempts"),
        "maxverifyattempts": (2, "attempts"),
        "verificationattempts": (2, "attempts"),
        "maxretries": (1, "attempts"),
        "maxverificationretries": (1, "attempts"),
        "verificationretries": (1, "attempts"),
    }

    def plan(cls, ancestors=()):
        if cls in ancestors:
            return None
        try:
            signature = inspect.signature(cls)
        except (TypeError, ValueError):
            return None

        hints = annotations_for(cls)
        arguments = []
        covered = set()

        for parameter in signature.parameters.values():
            if parameter.kind in (
                inspect.Parameter.VAR_POSITIONAL,
                inspect.Parameter.VAR_KEYWORD,
            ):
                continue

            key = normalize(parameter.name)
            if key in values:
                value, purpose = values[key]
                arguments.append((parameter, lambda value=value: value))
                covered.add(purpose)
                continue

            annotation = hints.get(parameter.name, parameter.annotation)
            candidates = annotation_classes(annotation)
            is_verification = any(
                word in key for word in ("verification", "verify", "validation")
            )
            is_configuration = any(
                word in key for word in ("config", "settings", "options")
            )

            if is_verification or is_configuration:
                for candidate in public_classes:
                    candidate_name = normalize(candidate.__name__)
                    words = (
                        ("verification", "verify", "validation")
                        if is_verification
                        else ("config", "settings", "options")
                    )
                    if any(word in candidate_name for word in words):
                        if candidate not in candidates:
                            candidates.append(candidate)

            choices = []
            for candidate in candidates:
                candidate_plan = plan(candidate, ancestors + (cls,))
                if candidate_plan is not None:
                    factory, purposes = candidate_plan
                    if purposes:
                        choices.append((factory, purposes))

            if choices:
                factory, purposes = max(
                    choices, key=lambda choice: len(choice[1])
                )
                arguments.append((parameter, factory))
                covered.update(purposes)
            elif parameter.default is inspect.Parameter.empty:
                return None

        def construct():
            positional = []
            keywords = {}
            for parameter, factory in arguments:
                value = factory()
                if parameter.kind is inspect.Parameter.POSITIONAL_ONLY:
                    positional.append(value)
                else:
                    keywords[parameter.name] = value
            return cls(*positional, **keywords)

        return construct, covered

    result = plan(agent_type)
    required = {"name", "engine", "judge", "attempts"}
    if result is None or not required.issubset(result[1]):
        raise TypeError(
            "Could not resolve LazyBridge's public Agent verification configuration."
        )

    return result[0]()

