def escaped_records(text: str) -> list[list[str]]:
    if not text:
        return []

    escapes = {"\\": "\\", "|": "|", '"': '"', "n": "\n"}
    records: list[list[str]] = []
    record: list[str] = []
    length = len(text)
    position = 0

    while True:
        field: list[str] = []
        quoted = position < length and text[position] == '"'
        closed = False

        if quoted:
            position += 1

        while position < length:
            character = text[position]

            if character == "\\":
                position += 1
                if position == length:
