import json


def indented_records(source: str) -> list[dict]:
    decoder = json.JSONDecoder()
    roots: list[dict] = []
    stack: list[dict] = []

    for line_number, line in enumerate(source.split("\n"), start=1):
        if line.endswith("\r"):
            line = line[:-1]

        position = 0
        columns = 0
        while position < len(line) and line[position] in " \t":
            if line[position] == " ":
                columns += 1
            else:
                columns += 4 - columns % 4
            position += 1

        if position == len(line) or line[position] == "#":
            continue

        if columns % 2:
            raise ValueError(f"Invalid indentation on line {line_number}")

        depth = columns // 2
        if depth > len(stack):
            raise ValueError(f"Skipped indentation level on line {line_number}")

        if line[position] != '"':
            raise ValueError(f"Expected a JSON string on line {line_number}")

        try:
            label, end = decoder.raw_decode(line, position)
        except json.JSONDecodeError as exc:
            raise ValueError(
                f"Invalid JSON string on line {line_number}"
            ) from exc

        while end < len(line) and line[end] in " \t":
            end += 1
        if end < len(line) and line[end] != "#":
            raise ValueError(f"Unexpected text on line {line_number}")

        node = {"label": label, "children": []}
        if depth == 0:
            roots.append(node)
        else:
            stack[depth - 1]["children"].append(node)

        del stack[depth:]
        stack.append(node)

    return roots

