def transaction_frames(
    initial: dict[str, int], commands: list[tuple]
) -> tuple[dict, list[bool]]:
    if not isinstance(initial, dict) or not isinstance(commands, list):
        raise ValueError("Expected a dictionary and a list of commands")

    for name, balance in initial.items():
        if (
            not isinstance(name, str)
            or type(balance) is not int
            or balance < 0
        ):
            raise ValueError("Invalid initial account or balance")

    balances = dict(initial)
    frames: list[tuple[dict[str, int], bool]] = []
    committed: list[bool] = []

    for command in commands:
        if (
            not isinstance(command, tuple)
            or not command
            or not isinstance(command[0], str)
        ):
            raise ValueError("Invalid command")

        operation = command[0]

        if operation == "move":
            if len(command) != 4:
                raise ValueError("Invalid move command")

            _, src, dst, amount = command
            if (
                not isinstance(src, str)
                or not isinstance(dst, str)
                or type(amount) is not int
                or amount < 0
                or src not in balances
                or dst not in balances
            ):
                raise ValueError("Invalid move")

            if frames and not frames[-1][1]:
                continue

            if src == dst or amount == 0:
                continue

            if amount > balances[src]:
                if frames:
                    frames[-1] = (frames[-1][0], False)
                continue

            if frames:
                undo = frames[-1][0]
                undo.setdefault(src, balances[src])
                undo.setdefault(dst, balances[dst])

            balances[src] -= amount
            balances[dst] += amount

        elif operation in ("begin", "commit", "rollback"):
            if len(command) != 1:
                raise ValueError("Invalid frame command")

            if operation == "begin":
                if frames and not frames[-1][1]:
                    raise ValueError("Cannot begin inside a failed frame")
                frames.append(({}, True))
                continue

            if not frames:
                raise ValueError("No open frame")

            undo, succeeded = frames.pop()

            if operation == "rollback" or not succeeded:
                balances.update(undo)
            elif frames:
                parent_undo = frames[-1][0]
                for name, original_balance in undo.items():
                    parent_undo.setdefault(name, original_balance)

            if operation == "commit":
                committed.append(succeeded)

        else:
            raise ValueError("Unknown command")

    if frames:
        raise ValueError("Unclosed frame")

    return balances, committed

