        ".config",
        ".policy",
        ".policies",
        ".engine",
        ".engines",
        ".engines.codex",
        ".agents",
        ".agents.codex",
        ".coding",
        ".coding_agent",
        ".coding_agents",
        ".coding_agents.codex",
    )

    for package in ("lazybridge", "lazy_bridge"):
        found = {}
        for suffix in module_paths:
            module_name = package + suffix
            try:
                module = importlib.import_module(module_name)
            except ModuleNotFoundError as exc:
                if exc.name and (
                    module_name == exc.name
                    or module_name.startswith(exc.name + ".")
