def wall_occurrences(start, stop, hour: int, minute: int) -> list:
    if type(hour) is not int or not 0 <= hour <= 23:
        raise ValueError("hour must be an exact int in 0..23")
    if type(minute) is not int or not 0 <= minute <= 59:
