    if not isinstance(start, datetime) or not isinstance(stop, datetime):
        raise ValueError("start and stop must be aware datetimes")
    if not isinstance(start.tzinfo, ZoneInfo):
        raise ValueError("start must use a ZoneInfo timezone")
