        raise ValueError("stop must use a ZoneInfo timezone")
    if start.tzinfo is not stop.tzinfo:
        raise ValueError("start and stop must share the identical timezone object")
    if start.utcoffset() is None or stop.utcoffset() is None:
        raise ValueError("start and stop must be aware datetimes")

    zone = start.tzinfo
    start_utc = start.astimezone(timezone.utc)
    stop_utc = stop.astimezone(timezone.utc)
    if start_utc > stop_utc:
        raise ValueError("start must not follow stop in UTC")

    occurrences = {}
    current_date = start.date()
    last_date = stop.date()

    while current_date <= last_date:
        wall = datetime(
            current_date.year,
            current_date.month,
            current_date.day,
            hour,
            minute,
        )

        for fold in (0, 1):
            candidate = wall.replace(tzinfo=zone, fold=fold)
            instant = candidate.astimezone(timezone.utc)
            normalized = instant.astimezone(zone)

            if normalized.replace(tzinfo=None) != wall:
                continue
            if start_utc <= instant < stop_utc:
                occurrences[instant] = normalized

        if current_date == last_date:
            break
        current_date += timedelta(days=1)

    return [occurrences[instant] for instant in sorted(occurrences)]

